// GJS turns whole numbers into ints, so float uniforms are nudged off the integer.
const INT_UNIFORMS = new Set([
    'octaves', 'vapor_octaves', 'corners_top', 'corners_bottom', 'fresnel_two_sided',
]);

function setUniform(effect, name, value) {
    if (INT_UNIFORMS.has(name))
        effect.set_uniform_value(name, Math.trunc(value));
    else
        effect.set_uniform_value(name, parseFloat(value) - 1e-6);
}

function log(message) {
    console.log('[Liquid Vapor Glass] ' + message);
}

// One shared timeline drives every animated effect and is stopped when none is left.
class FlowTicker {
    static _tasks = new Set();
    static _timeline = null;

    static add(task) {
        this._tasks.add(task);
        if (this._timeline)
            return;

        this._timeline = new Clutter.Timeline({
            actor: global.stage,
            duration: 5000,
            repeat_count: -1,
        });
        this._timeline.connect('new-frame', timeline => {
            const delta = timeline.get_delta();
            for (const tick of this._tasks)
                tick(delta);
        });
        this._timeline.start();
    }

    static remove(task) {
        if (!this._tasks.delete(task) || this._tasks.size > 0)
            return;

        this._timeline?.stop();
        this._timeline = null;
    }
}

// Pass 1: wave + vapor + water.
const VaporWaveEffect = GObject.registerClass({
    GTypeName: 'LvgVaporWaveEffect',
}, class LvgVaporWaveEffect extends Clutter.ShaderEffect {
    constructor(uniforms) {
        super();

        this._phase = 0;
        this._sinceRepaint = 0;
        this._tick = this._onTick.bind(this);

        this.set_shader_source(VAPOR_GLSL);
        for (const [name, value] of Object.entries(uniforms))
            setUniform(this, name, value);
        setUniform(this, 'time', 0);
        setUniform(this, 'clip_x0', 0);
        setUniform(this, 'clip_y0', 0);
        setUniform(this, 'clip_width', -1);
        setUniform(this, 'clip_height', -1);
    }

    setGeometry(width, height) {
        setUniform(this, 'width', width);
        setUniform(this, 'height', height);
        setUniform(this, 'surface_max_size', Math.max(width, height));
        this.queue_repaint();
    }

    setAnimating(active) {
        if (active && CONFIG.flow.enabled && CONFIG.flow.speed > 0)
            FlowTicker.add(this._tick);
        else
            FlowTicker.remove(this._tick);
    }

    // The phase loops 0..TAU and every moving term in the shader uses an integer
    // multiple of it, so the animation never jumps.
    _onTick(deltaMs) {
        this._phase = (this._phase + deltaMs * TIME_FACTOR * CONFIG.flow.speed) % TAU;
        this._sinceRepaint += deltaMs;
        const interval = 1000 / CONFIG.flow.maxFps;
        if (this._sinceRepaint < interval)
            return;

        this._sinceRepaint %= interval;
        setUniform(this, 'time', this._phase);
        this.queue_repaint();
    }

    vfunc_set_actor(actor) {
        super.vfunc_set_actor(actor);
        if (!actor)
            FlowTicker.remove(this._tick);
    }

    vfunc_paint_target(node = null, context = null) {
        this.set_uniform_value('tex', 0);
        if (node && context)
            super.vfunc_paint_target(node, context);
        else if (node)
            super.vfunc_paint_target(node);
        else
            super.vfunc_paint_target();
    }
});

// Pass 2: liquid glass (edge refraction, dispersion, rim light, tint, inner shadow).
const LiquidGlassEffect = GObject.registerClass({
    GTypeName: 'LvgLiquidGlassEffect',
}, class LvgLiquidGlassEffect extends Clutter.ShaderEffect {
    constructor(uniforms) {
        super();

        this._u = uniforms;
        this._width = 1;
        this._height = 1;
        this._scale = 1;
        this._resourceScale = 0;

        this.set_shader_source(GLASS_GLSL);
        for (const [name, value] of Object.entries(uniforms)) {
            if (name !== 'edge_size' && name !== 'reach' && name !== 'corner_radius')
                setUniform(this, name, value);
        }
        setUniform(this, 'clip_x0', 0);
        setUniform(this, 'clip_y0', 0);
        setUniform(this, 'clip_width', -1);
        setUniform(this, 'clip_height', -1);
        setUniform(this, 'aa_width', 1);
        this._applyScaled();
    }

    setGeometry(width, height, scale) {
        this._width = width;
        this._height = height;
        this._scale = scale;
        setUniform(this, 'width', width);
        setUniform(this, 'height', height);
        this._applyScaled();
        this.queue_repaint();
    }

    // Sizes are written in logical px and scaled like Blur my Shell does.
    _applyScaled() {
        const maxEdge = Math.max(1, Math.min(this._width, this._height) / 2);
        setUniform(this, 'edge_size', Math.min(this._u.edge_size * this._scale, maxEdge));
        setUniform(this, 'reach', Math.min(this._u.reach * this._scale, maxEdge));
        setUniform(this, 'corner_radius', Math.min(this._u.corner_radius * this._scale, maxEdge));
        setUniform(this, 'scale_factor', this._scale);
    }

    vfunc_paint_target(node = null, context = null) {
        this.set_uniform_value('tex', 0);

        // one device pixel, in logical px, for the anti-aliased edge
        const actor = this.get_actor();
        const resourceScale = actor?.get_resource_scale?.() ?? 1;
        if (resourceScale > 0 && resourceScale !== this._resourceScale) {
            this._resourceScale = resourceScale;
            setUniform(this, 'aa_width', 1 / resourceScale);
        }

        if (node && context)
            super.vfunc_paint_target(node, context);
        else if (node)
            super.vfunc_paint_target(node);
        else
            super.vfunc_paint_target();
    }
});

function stageRect(actor) {
    const extents = actor.get_transformed_extents();
    const rect = {
        x: extents.get_x(),
        y: extents.get_y(),
        width: extents.get_width(),
        height: extents.get_height(),
    };
    return Object.values(rect).every(Number.isFinite) ? rect : null;
}

// A glass surface that follows its target actor. The widget holds a monitor-sized copy of the wallpaper,
// offset so the part under the surface lines up with the real wallpaper, and is clipped to
// the surface by its own allocation. Both effects see exactly the surface, so the shaders
// work on the whole texture.
class GlassSurface {
    constructor(name, host, getTarget, config) {
        this._getTarget = getTarget;
        this._connections = [];
        this._destroyed = false;

        const monitor = Main.layoutManager.primaryMonitor;
        this._monitorIndex = Main.layoutManager.primaryIndex;

        // Zero-sized holder: the host may be a layout that would otherwise make room for it.
        this._container = new St.Widget({
            name: 'lvg-' + name + '-container',
            x_align: Clutter.ActorAlign.START,
            y_align: Clutter.ActorAlign.START,
            width: 0,
            height: 0,
            reactive: false,
        });
        this._glass = new St.Widget({
            name: 'lvg-' + name,
            clip_to_allocation: true,
            reactive: false,
        });
        this._container.add_child(this._glass);

        // Same wallpaper trick as Blur my Shell: an invisible source holds the background,
        // and a clone of it is what the effects capture, so live wallpapers keep updating.
        this._source = new St.Widget({ name: 'lvg-' + name + '-source', opacity: 0 });
        this._source.set_size(monitor.width, monitor.height);
        this._glass.add_child(this._source);
        this._clone = new Clutter.Clone({ source: this._source });
        this._glass.add_child(this._clone);

        this._bgManager = new Background.BackgroundManager({
            container: this._source,
            monitorIndex: this._monitorIndex,
            controlPosition: false,
        });
        this._source.connect('child-added', (container, child) => {
            container.set_child_below_sibling(child, null);
        });

        this._vapor = new VaporWaveEffect(config.vapor);
        this._glassFx = new LiquidGlassEffect(config.glass);
        this._glass.add_effect_with_name('lvg-vapor', this._vapor);
        this._glass.add_effect_with_name('lvg-glass', this._glassFx);

        host.insert_child_at_index(this._container, 0);

        const target = getTarget();
        this._targetActor = target;
        this._connect(target, 'notify::allocation', () => this.sync());
        this._connect(this._glass, 'notify::mapped', () => this._updateAnimation());
        this._connect(this._glass, 'notify::allocation', () => this._updateAnimation());

        this.sync();
        this._updateAnimation();
    }

    _connect(object, signal, handler) {
        this._connections.push([object, object.connect(signal, handler)]);
    }

    _updateAnimation() {
        if (this._destroyed)
            return;
        const width = this._glass.width;
        this._vapor.setAnimating(this._glass.mapped && width > 0);
    }

    sync() {
        if (this._destroyed)
            return;

        const rect = stageRect(this._targetActor);
        const monitor = Main.layoutManager.primaryMonitor;
        const [cx, cy] = this._container.get_transformed_position();
        if (!rect || !monitor || !Number.isFinite(cx) || !Number.isFinite(cy))
            return;

        const x = Math.round(rect.x);
        const y = Math.round(rect.y);
        const width = Math.max(1, Math.round(rect.width));
        const height = Math.max(1, Math.round(rect.height));

        this._glass.set_position(x - Math.round(cx), y - Math.round(cy));
        this._glass.set_size(width, height);

        // wallpaper offset so that this widget shows the wallpaper under it
        const offsetX = monitor.x - x;
        const offsetY = monitor.y - y;
        this._source.set_position(offsetX, offsetY);
        this._clone.set_position(offsetX, offsetY);
        this._clone.set_size(monitor.width, monitor.height);

        const scale = St.ThemeContext.get_for_stage(global.stage).scale_factor;
        this._vapor.setGeometry(width, height);
        this._glassFx.setGeometry(width, height, scale);
    }

    destroy() {
        this._destroyed = true;
        for (const [object, id] of this._connections) {
            try {
                object.disconnect(id);
            } catch (e) {
                // already destroyed
            }
        }
        this._connections = [];

        this._vapor.setAnimating(false);
        this._glass.remove_effect_by_name('lvg-vapor');
        this._glass.remove_effect_by_name('lvg-glass');
        this._bgManager.destroy();
        this._container.destroy();
    }
}

export default class LiquidVaporGlassExtension extends Extension {
    enable() {
        this._surfaces = [];
        this._signals = []; // startup-complete only
        this._watchers = []; // rebuilt together with the surfaces
        this._styled = [];

        if (Main.layoutManager._startingUp) {
            const id = Main.layoutManager.connect('startup-complete', () => {
                Main.layoutManager.disconnect(id);
                this._signals = this._signals.filter(entry => entry[1] !== id);
                this._build();
            });
            this._signals.push([Main.layoutManager, id]);
        } else {
            this._build();
        }
    }

    disable() {
        for (const [object, id] of this._signals ?? []) {
            try {
                object.disconnect(id);
            } catch (e) {
                // already gone
            }
        }
        this._signals = [];
        this._teardown();
        this._surfaces = null;
        this._watchers = null;
        this._styled = null;
    }

    _build() {
        this._teardown();

        try {
            if (CONFIG.surfaces.panel.enabled) {
                const panelBox = Main.layoutManager.panelBox;
                this._surfaces.push(new GlassSurface(
                    'panel', panelBox, () => Main.panel, CONFIG.surfaces.panel));
                Main.panel.add_style_class_name('lvg-glass-panel');
                this._styled.push([Main.panel, 'lvg-glass-panel']);
            }
        } catch (e) {
            log('could not build the panel glass: ' + e);
        }

        try {
            const dash = Main.overview.dash;
            if (CONFIG.surfaces.dash.enabled && dash?._background) {
                this._surfaces.push(new GlassSurface(
                    'dash', dash, () => dash._background, CONFIG.surfaces.dash));
                dash.add_style_class_name('lvg-glass-dash');
                this._styled.push([dash, 'lvg-glass-dash']);
            }
        } catch (e) {
            log('could not build the dash glass: ' + e);
        }

        const resync = () => this._surfaces?.forEach(surface => surface.sync());
        const watch = (object, signal, handler) =>
            this._watchers.push([object, object.connect(signal, handler)]);

        watch(Main.layoutManager, 'monitors-changed', () => this._build());
        watch(Main.overview, 'showing', resync);
        watch(Main.overview, 'shown', resync);
        watch(Main.overview, 'hiding', resync);
    }

    _teardown() {
        for (const [object, id] of this._watchers ?? []) {
            try {
                object.disconnect(id);
            } catch (e) {
                // already gone
            }
        }
        if (this._watchers)
            this._watchers.length = 0;

        for (const surface of this._surfaces ?? [])
            surface.destroy();
        if (this._surfaces)
            this._surfaces.length = 0;

        for (const [actor, styleClass] of this._styled ?? []) {
            try {
                actor.remove_style_class_name(styleClass);
            } catch (e) {
                // actor already destroyed
            }
        }
        if (this._styled)
            this._styled.length = 0;
    }
}
